// src/components/common/KPICard.jsx
import React from 'react';
import { TrendingUp, TrendingDown, Minus } from 'lucide-react';

const KPICard = ({ title, value, subtitle, trend, icon: Icon, loading }) => {
  const getTrendIcon = () => {
    if (trend > 0) return <TrendingUp size={16} className="trend-up" />;
    if (trend < 0) return <TrendingDown size={16} className="trend-down" />;
    return <Minus size={16} className="trend-neutral" />;
  };

  return (
    <div className="kpi-card">
      <div className="kpi-header">
        <span className="kpi-title">{title}</span>
        {Icon && (
          <div className="kpi-icon">
            <Icon size={24} />
          </div>
        )}
      </div>
      
      {loading ? (
        <div className="kpi-skeleton"></div>
      ) : (
        <>
          <div className="kpi-value">{value}</div>
          {subtitle && (
            <div className="kpi-subtitle">
              {trend !== undefined && getTrendIcon()}
              <span>{subtitle}</span>
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default KPICard;
