// src/components/stats/StatCard.jsx
import React, { useState, useEffect } from 'react';
import {
  BarChart, Bar,
  LineChart, Line,
  PieChart, Pie, Cell,
  XAxis, YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer
} from 'recharts';
import { statsService } from '../../services/api';
import LoadingSpinner from '../common/LoadingSpinner';
import { Trash2, RefreshCw } from 'lucide-react';

const COLORS = ['#16a34a', '#22c55e', '#4ade80', '#86efac', '#bbf7d0', '#dcfce7', '#f0fdf4'];

const StatCard = ({ chart, filters, onRemove }) => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [total, setTotal] = useState(0);

  useEffect(() => {
    fetchData();
  }, [filters, chart]);

  const fetchData = async () => {
    setLoading(true);
    try {
      const result = await statsService.getStats({
        metric: chart.metric,
        dimension: chart.dimension,
        filters: filters
      });
      
      setData(result);
      const sum = result.reduce((acc, item) => acc + parseFloat(item.value), 0);
      setTotal(sum);
    } catch (error) {
      console.error('Erreur chargement données:', error);
      setData([]);
      setTotal(0);
    } finally {
      setLoading(false);
    }
  };

  const renderChart = () => {
    if (loading) {
      return (
        <div className="chart-loading">
          <LoadingSpinner size="md" />
          <p>Chargement des données...</p>
        </div>
      );
    }

    if (!data || data.length === 0) {
      return (
        <div className="chart-empty">
          <p>😕</p>
          <span>Aucune donnée disponible</span>
        </div>
      );
    }

    const chartProps = {
      data,
      margin: { top: 20, right: 30, left: 20, bottom: 60 }
    };

    switch (chart.chartType) {
      case 'line':
        return (
          <ResponsiveContainer width="100%" height={320}>
            <LineChart {...chartProps}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
              <XAxis 
                dataKey="label" 
                angle={-45}
                textAnchor="end"
                height={80}
                style={{ fontSize: '11px' }}
                stroke="#6b7280"
              />
              <YAxis 
                style={{ fontSize: '11px' }}
                stroke="#6b7280"
              />
              <Tooltip 
                contentStyle={{
                  backgroundColor: '#fff',
                  border: '1px solid #e5e7eb',
                  borderRadius: '8px',
                  fontSize: '12px'
                }}
              />
              <Line
                type="monotone"
                dataKey="value"
                stroke="#16a34a"
                strokeWidth={3}
                dot={{ fill: '#16a34a', r: 5 }}
                activeDot={{ r: 7 }}
                name="Nombre"
              />
            </LineChart>
          </ResponsiveContainer>
        );

      case 'pie':
        return (
          <ResponsiveContainer width="100%" height={320}>
            <PieChart>
              <Pie
                data={data}
                cx="50%"
                cy="50%"
                labelLine={true}
                label={({ label, value, percent }) => 
                  `${label}: ${value} (${(percent * 100).toFixed(0)}%)`
                }
                outerRadius={110}
                dataKey="value"
              >
                {data.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip 
                contentStyle={{
                  backgroundColor: '#fff',
                  border: '1px solid #e5e7eb',
                  borderRadius: '8px',
                  fontSize: '12px'
                }}
              />
            </PieChart>
          </ResponsiveContainer>
        );

      default: // bar
        return (
          <ResponsiveContainer width="100%" height={320}>
            <BarChart {...chartProps}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
              <XAxis 
                dataKey="label" 
                angle={-45}
                textAnchor="end"
                height={80}
                style={{ fontSize: '11px' }}
                stroke="#6b7280"
              />
              <YAxis 
                style={{ fontSize: '11px' }}
                stroke="#6b7280"
              />
              <Tooltip 
                contentStyle={{
                  backgroundColor: '#fff',
                  border: '1px solid #e5e7eb',
                  borderRadius: '8px',
                  fontSize: '12px'
                }}
              />
              <Bar
                dataKey="value"
                fill="#16a34a"
                radius={[8, 8, 0, 0]}
                name="Nombre"
              />
            </BarChart>
          </ResponsiveContainer>
        );
    }
  };

  return (
    <div className="stat-card">
      <div className="stat-card-header">
        <h3>{chart.title}</h3>
        <div className="stat-card-actions">
          <button 
            className="icon-btn" 
            onClick={fetchData}
            title="Actualiser"
          >
            <RefreshCw size={16} />
          </button>
          {!chart.isDefault && onRemove && (
            <button 
              className="icon-btn" 
              onClick={onRemove}
              title="Supprimer"
            >
              <Trash2 size={16} />
            </button>
          )}
        </div>
      </div>

      <div className="stat-card-body">
        {renderChart()}
      </div>

      {data.length > 0 && (
        <div className="stat-card-footer">
          <div className="stat-info">
            <span className="stat-label">Total :</span>
            <span className="stat-value">{Math.round(total)}</span>
          </div>
          <div className="stat-info">
            <span className="stat-label">Entrées :</span>
            <span className="stat-value">{data.length}</span>
          </div>
        </div>
      )}
    </div>
  );
};

export default StatCard;
