// src/components/dashboard/RegionsTable.jsx
import React from 'react';
import { MapPin } from 'lucide-react';
import { PieChart, Pie, Cell, ResponsiveContainer, Legend, Tooltip } from 'recharts';

const COLORS = {
  new: '#3b82f6',        // Bleu
  assigned: '#8b5cf6',   // Violet
  in_progress: '#f59e0b', // Orange
  resolved: '#16a34a',   // Vert
  closed: '#6b7280'      // Gris
};

const STATUS_LABELS = {
  new: 'Nouveau',
  assigned: 'Assignée',
  in_progress: 'En cours',
  resolved: 'Résolue',
  closed: 'Fermée'
};

const RegionsTable = ({ regions, loading }) => {
  if (loading) {
    return (
      <div style={{ padding: '40px', textAlign: 'center', background: 'white', borderRadius: '12px', marginTop: '32px' }}>
        Chargement des régions...
      </div>
    );
  }

  if (!regions || regions.length === 0) {
    return (
      <div style={{ padding: '40px', textAlign: 'center', background: 'white', borderRadius: '12px', marginTop: '32px' }}>
        <MapPin size={48} style={{ margin: '0 auto 16px', color: '#9ca3af' }} />
        <p>Aucune région trouvée</p>
      </div>
    );
  }

  // Fonction pour préparer les données du pie chart
  const getPieData = (region) => {
    const data = [];
    
    if (region.new_complaints > 0) {
      data.push({ name: 'Nouveau', value: region.new_complaints, status: 'new' });
    }
    if (region.assigned_complaints > 0) {
      data.push({ name: 'Assignée', value: region.assigned_complaints, status: 'assigned' });
    }
    if (region.in_progress_complaints > 0) {
      data.push({ name: 'En cours', value: region.in_progress_complaints, status: 'in_progress' });
    }
    if (region.resolved_complaints > 0) {
      data.push({ name: 'Résolue', value: region.resolved_complaints, status: 'resolved' });
    }
    if (region.closed_complaints > 0) {
      data.push({ name: 'Fermée', value: region.closed_complaints, status: 'closed' });
    }

    return data;
  };

  return (
    <div style={{
      background: 'white',
      borderRadius: '12px',
      border: '1px solid #e5e7eb',
      marginTop: '32px',
      overflow: 'hidden'
    }}>
      {/* Header */}
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        padding: '20px 24px',
        borderBottom: '1px solid #e5e7eb',
        background: '#f9fafb'
      }}>
        <h3 style={{
          display: 'flex',
          alignItems: 'center',
          gap: '10px',
          fontSize: '18px',
          fontWeight: '600',
          margin: 0
        }}>
          <MapPin size={20} />
          Statistiques par région
        </h3>
        <span style={{
          fontSize: '13px',
          color: '#6b7280',
          background: 'white',
          padding: '4px 12px',
          borderRadius: '12px',
          border: '1px solid #e5e7eb'
        }}>
          {regions.length} région(s)
        </span>
      </div>

      {/* Grille de cartes par région */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fill, minmax(400px, 1fr))',
        gap: '24px',
        padding: '24px'
      }}>
        {regions.map((region) => {
          const pieData = getPieData(region);
          const resolutionRate = region.total_complaints > 0
            ? ((region.resolved_complaints / region.total_complaints) * 100).toFixed(1)
            : 0;

          return (
            <div 
              key={region.id}
              style={{
                border: '1px solid #e5e7eb',
                borderRadius: '12px',
                padding: '20px',
                borderLeft: `4px solid ${region.color_hex || '#16a34a'}`,
                background: 'white'
              }}
            >
              {/* En-tête de la carte région */}
              <div style={{ marginBottom: '16px' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '8px' }}>
                  <div style={{
                    width: '16px',
                    height: '16px',
                    borderRadius: '50%',
                    background: region.color_hex || '#16a34a'
                  }}></div>
                  <h4 style={{ margin: 0, fontSize: '18px', fontWeight: '600' }}>
                    {region.name}
                  </h4>
                </div>
                <div style={{ fontSize: '13px', color: '#6b7280', marginLeft: '28px' }}>
                  {region.code} • {region.population?.toLocaleString('fr-DZ') || 'N/A'} habitants
                </div>
              </div>

              {/* Statistiques rapides */}
              <div style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(3, 1fr)',
                gap: '12px',
                marginBottom: '20px',
                padding: '12px',
                background: '#f9fafb',
                borderRadius: '8px'
              }}>
                <div style={{ textAlign: 'center' }}>
                  <div style={{ fontSize: '24px', fontWeight: '700', color: '#1f2937' }}>
                    {region.total_complaints}
                  </div>
                  <div style={{ fontSize: '12px', color: '#6b7280', marginTop: '4px' }}>
                    Total
                  </div>
                </div>
                <div style={{ textAlign: 'center' }}>
                  <div style={{ fontSize: '24px', fontWeight: '700', color: '#f59e0b' }}>
                    {region.open_complaints}
                  </div>
                  <div style={{ fontSize: '12px', color: '#6b7280', marginTop: '4px' }}>
                    Ouvertes
                  </div>
                </div>
                <div style={{ textAlign: 'center' }}>
                  <div style={{ fontSize: '24px', fontWeight: '700', color: '#16a34a' }}>
                    {region.resolved_complaints}
                  </div>
                  <div style={{ fontSize: '12px', color: '#6b7280', marginTop: '4px' }}>
                    Résolues
                  </div>
                </div>
              </div>

              {/* Graphique Pie Chart */}
              {pieData.length > 0 ? (
                <div style={{ height: '250px' }}>
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={pieData}
                        cx="50%"
                        cy="50%"
                        labelLine={false}
                        label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                        outerRadius={80}
                        dataKey="value"
                      >
                        {pieData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={COLORS[entry.status]} />
                        ))}
                      </Pie>
                      <Tooltip 
                        formatter={(value) => `${value} plainte${value > 1 ? 's' : ''}`}
                      />
                      <Legend 
                        verticalAlign="bottom" 
                        height={36}
                        formatter={(value) => STATUS_LABELS[value] || value}
                      />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              ) : (
                <div style={{
                  height: '250px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  color: '#9ca3af',
                  fontSize: '14px'
                }}>
                  Aucune plainte pour cette région
                </div>
              )}

              {/* Barre de progression */}
              <div style={{ marginTop: '20px' }}>
                <div style={{ 
                  display: 'flex', 
                  justifyContent: 'space-between', 
                  marginBottom: '8px',
                  fontSize: '13px',
                  color: '#6b7280'
                }}>
                  <span>Taux de résolution</span>
                  <span style={{ fontWeight: '600', color: '#1f2937' }}>{resolutionRate}%</span>
                </div>
                <div style={{
                  height: '10px',
                  background: '#e5e7eb',
                  borderRadius: '5px',
                  overflow: 'hidden'
                }}>
                  <div style={{
                    height: '100%',
                    width: `${resolutionRate}%`,
                    background: resolutionRate >= 70 ? '#16a34a' : resolutionRate >= 40 ? '#f59e0b' : '#ef4444',
                    borderRadius: '5px',
                    transition: 'width 0.3s ease'
                  }}></div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Footer - Résumé global */}
      <div style={{
        display: 'flex',
        justifyContent: 'space-around',
        padding: '20px 24px',
        background: '#f9fafb',
        borderTop: '1px solid #e5e7eb',
        fontSize: '14px'
      }}>
        <div style={{ textAlign: 'center' }}>
          <div style={{ fontSize: '24px', fontWeight: '700', color: '#1f2937' }}>
            {regions.reduce((sum, r) => sum + r.total_complaints, 0)}
          </div>
          <div style={{ color: '#6b7280', marginTop: '4px' }}>Plaintes totales</div>
        </div>
        <div style={{ textAlign: 'center' }}>
          <div style={{ fontSize: '24px', fontWeight: '700', color: '#f59e0b' }}>
            {regions.reduce((sum, r) => sum + r.open_complaints, 0)}
          </div>
          <div style={{ color: '#6b7280', marginTop: '4px' }}>Ouvertes</div>
        </div>
        <div style={{ textAlign: 'center' }}>
          <div style={{ fontSize: '24px', fontWeight: '700', color: '#16a34a' }}>
            {regions.reduce((sum, r) => sum + r.resolved_complaints, 0)}
          </div>
          <div style={{ color: '#6b7280', marginTop: '4px' }}>Résolues</div>
        </div>
      </div>
    </div>
  );
};

export default RegionsTable;
