// src/components/dashboard/ComplaintsChart.jsx
import React, { useState, useEffect } from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer
} from 'recharts';
import { dashboardService } from '../../services/api';
import LoadingSpinner from '../common/LoadingSpinner';

const ComplaintsChart = () => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [period, setPeriod] = useState('30'); // 7, 30, 90 jours

  useEffect(() => {
    fetchData();
  }, [period]);

  const fetchData = async () => {
    setLoading(true);
    try {
      const result = await dashboardService.getComplaintsTrend(period);
      setData(result);
    } catch (error) {
      console.error('Erreur chargement graphique:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <LoadingSpinner />;
  }

  return (
    <div>
      <div className="chart-controls">
        <button
          className={`period-btn ${period === '7' ? 'active' : ''}`}
          onClick={() => setPeriod('7')}
        >
          7 jours
        </button>
        <button
          className={`period-btn ${period === '30' ? 'active' : ''}`}
          onClick={() => setPeriod('30')}
        >
          30 jours
        </button>
        <button
          className={`period-btn ${period === '90' ? 'active' : ''}`}
          onClick={() => setPeriod('90')}
        >
          90 jours
        </button>
      </div>

      <ResponsiveContainer width="100%" height={300}>
        <LineChart data={data}>
          <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
          <XAxis 
            dataKey="date" 
            stroke="#6b7280"
            style={{ fontSize: '12px' }}
          />
          <YAxis 
            stroke="#6b7280"
            style={{ fontSize: '12px' }}
          />
          <Tooltip 
            contentStyle={{
              backgroundColor: '#fff',
              border: '1px solid #e5e7eb',
              borderRadius: '8px'
            }}
          />
          <Legend />
          <Line
            type="monotone"
            dataKey="count"
            stroke="#16a34a"
            strokeWidth={2}
            name="Nombre de plaintes"
            dot={{ fill: '#16a34a', r: 4 }}
            activeDot={{ r: 6 }}
          />
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
};

export default ComplaintsChart;
