// src/services/api.js
import axios from 'axios';

const API_URL = import.meta.env.VITE_API_URL || '/api';

const api = axios.create({
  baseURL: 'https://nadhif.yanlouggani.dev/admin/api',  // URL absolue
  timeout: 10000,
  headers: {
    'Content-Type': 'application/json',
  },
});


// Intercepteur pour logger les requêtes
api.interceptors.request.use(
  (config) => {
    console.log('🚀 Requête:', config.method.toUpperCase(), config.url, config.data);
    return config;
  },
  (error) => {
    console.error('❌ Erreur requête:', error);
    return Promise.reject(error);
  }
);

// Intercepteur pour logger les réponses
api.interceptors.response.use(
  (response) => {
    console.log('✅ Réponse:', response.config.url, response.data);
    return response;
  },
  (error) => {
    console.error('❌ Erreur réponse:', error.response?.status, error.response?.data);
    return Promise.reject(error);
  }
);

// Service Stats
export const statsService = {
  // Pour les graphiques de la page Stats
  getStats: async (params) => {
    try {
      console.log('📊 statsService.getStats appelé avec:', params);
      const { data } = await api.post('/stats/stats', params);
      console.log('📊 statsService.getStats résultat:', data);
      return data.data || [];
    } catch (error) {
      console.error('❌ Erreur getStats:', error);
      return [];
    }
  },

  // Pour les KPIs filtrés
  getFilteredKPIs: async (filters) => {
    try {
      const { data } = await api.post('/stats/kpis', filters);
      return data.data;
    } catch (error) {
      console.error('❌ Erreur getFilteredKPIs:', error);
      return {
        total: 0,
        open: 0,
        resolved: 0,
        closed: 0,
        open_percentage: 0,
        resolved_percentage: 0,
        closed_percentage: 0,
        avg_resolution: 0,
        total_regions: 0,
        active_teams: 0,
        sla_48h: 0
      };
    }
  },

  // Régions
  getRegions: async () => {
    try {
      const { data } = await api.get('/stats/regions');
      return data.data || [];
    } catch (error) {
      console.error('❌ Erreur getRegions:', error);
      return [];
    }
  },

  // Équipes
  getTeams: async () => {
    try {
      const { data } = await api.get('/stats/teams');
      return data.data || [];
    } catch (error) {
      console.error('❌ Erreur getTeams:', error);
      return [];
    }
  }
};

