// src/components/layout/Sidebar.jsx
import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { ChevronDown, ChevronRight } from 'lucide-react';
import { sidebarConfig } from '../../config/sidebarConfig';

const Sidebar = () => {
  const location = useLocation();
  const [expandedSections, setExpandedSections] = useState(['dashboard']);

  const toggleSection = (sectionId) => {
    setExpandedSections(prev =>
      prev.includes(sectionId)
        ? prev.filter(id => id !== sectionId)
        : [...prev, sectionId]
    );
  };

  const isActive = (path) => location.pathname === path;

  return (
    <aside className="sidebar">
      <div className="sidebar-header">
        <h1 className="sidebar-logo">NADHIF</h1>
        <p className="sidebar-subtitle">Gestion des déchets</p>
      </div>

      <nav className="sidebar-nav">
        {sidebarConfig.map(section => (
          <div key={section.id} className="sidebar-section">
            {section.items ? (
              <>
                <button
                  onClick={() => toggleSection(section.id)}
                  className="sidebar-section-button"
                >
                  <div className="sidebar-section-left">
                    <section.icon size={20} />
                    <span>{section.label}</span>
                  </div>
                  {expandedSections.includes(section.id) ? (
                    <ChevronDown size={16} />
                  ) : (
                    <ChevronRight size={16} />
                  )}
                </button>
                {expandedSections.includes(section.id) && (
                  <div className="sidebar-subsection">
                    {section.items.map(item => (
                      <Link
                        key={item.id}
                        to={item.path}
                        className={`sidebar-link ${isActive(item.path) ? 'active' : ''}`}
                      >
                        {item.label}
                      </Link>
                    ))}
                  </div>
                )}
              </>
            ) : (
              <Link
                to={section.path}
                className={`sidebar-section-button ${isActive(section.path) ? 'active' : ''}`}
              >
                <div className="sidebar-section-left">
                  <section.icon size={20} />
                  <span>{section.label}</span>
                </div>
                {!section.developed && (
                  <span className="badge-soon">Bientôt</span>
                )}
              </Link>
            )}
          </div>
        ))}
      </nav>
    </aside>
  );
};

export default Sidebar;
